pub fn fixture_mp4_with_undecodable_video() -> Vec<u8> {
    let mut mp4 = fixture_h264_mp4();
    let mdat = mp4
        .windows(4)
        .position(|window| window == b"mdat")
        .filter(|offset| *offset >= 4)
        .expect("fixture mp4 has an mdat box");
    let box_start = mdat - 4;
    let box_size = u32::from_be_bytes([
        mp4[box_start],
        mp4[box_start + 1],
        mp4[box_start + 2],
        mp4[box_start + 3],
    ]) as usize;
    let payload_end = box_start + box_size;
    assert!(payload_end <= mp4.len() && box_size > 8);
    mp4[mdat + 4..payload_end].fill(0);
    mp4
}
